import{_ as o,o as d,c,ag as a}from"./chunks/framework.DyxC4IQh.js";const u=JSON.parse('{"title":"方向键光标","description":"用 WASD 或 HJKL 把光标按屏幕坐标走到元素上再点，包括贴边并排、走进容器和四秒超时。","frontmatter":{"description":"用 WASD 或 HJKL 把光标按屏幕坐标走到元素上再点，包括贴边并排、走进容器和四秒超时。"},"headers":[],"relativePath":"guide/cursor.md","filePath":"guide/cursor.md","lastUpdated":1792384961000}'),t={name:"guide/cursor.md"};function r(i,e,p,n,h,s){return d(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="方向键光标" tabindex="-1">方向键光标 <a class="header-anchor" href="#方向键光标" aria-label="Permalink to &quot;方向键光标&quot;">​</a></h1><p>标签够用。目标密集成一片时，你要找的那一个往往要两个字母，眼睛得把满屏标签扫一遍；想把屏幕一排排看下去，逐个找标签同样麻烦。这两种情况下用方向键，把光标走到框上再点。</p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><p>按 <code>W</code> <code>A</code> <code>S</code> <code>D</code> 或 <code>H</code> <code>J</code> <code>K</code> <code>L</code>。屏幕上还没有光标时，方向键从屏幕中心起算：第一次按下，光标锚在中心那个方向上离你最近的可点击元素，周围画一圈绿框（半透明填充）。</p><p>此后按方向键在元素之间走，按点击键（hint 模式内固定 <code>Space</code>；模式外用设置里的光标点击键，默认 <code>Space</code>，可切 <code>Enter</code>）点它。hint 模式外按 <code>Esc</code> 清除光标；hint 模式内 <code>Esc</code> 退出的是 hint 模式，光标留在原地。</p><p>光标不依赖 hint 模式。不开 <code>F</code>，光靠方向键加一个点击键也能用完整套导航。</p><h2 id="走位按屏幕几何-不按控件树" tabindex="-1">走位按屏幕几何，不按控件树 <a class="header-anchor" href="#走位按屏幕几何-不按控件树" aria-label="Permalink to &quot;走位按屏幕几何，不按控件树&quot;">​</a></h2><p>一次按键一次选择：按下去的时候，屏幕上现成的候选表被扫一遍，取那个方向上最近的一个。没有预先算好的邻接表，也没有层级栈，界面滚动或改版都不需要重建什么。</p><p>候选有两条入场路子。</p><p>边缘错开：目标在你按的这个方向上跟你的框完全不重叠。往右走，左边缘落在你右边缘以内的都不算。列表一行行紧挨着、按钮一颗挨一颗，贴边并排的算邻居，压过来一个像素就不算。</p><p>跟你重叠、中心更靠那个方向：开关在你站的这一行里，卡片里的按钮在卡片里，它们永远越不过你外侧那条边，光靠第一条够不着。所以跟你的框有重叠、且中心点落在你中心点那一侧的，也算候选。</p><p>打分是主轴距离加上侧向距离的两倍。错开的目标按边缘间距算，重叠的按中心间距算。正对着你的邻居胜过斜上方的邻居，横向偏移过大的候选被降权，长列表里连着按 <code>J</code>，落点尽量留在同一列。</p><p>8 像素一行的容差只用在贴标签的阅读顺序上。走位没有容差：压过来一个像素就不算这个方向的邻居，正好贴边则算。</p><h2 id="走进容器-也走得回来" tabindex="-1">走进容器，也走得回来 <a class="header-anchor" href="#走进容器-也走得回来" aria-label="Permalink to &quot;走进容器，也走得回来&quot;">​</a></h2><p>设置页每一行整行可点，行尾一个开关。光标停在行上按 <code>L</code>：行右边没有别的东西，重叠那条判定把开关递给你。再按 <code>L</code>，开关外侧还是没东西，光标原地不动；要回行本身按 <code>H</code>，行跟开关重叠、行的中心在开关左侧，一按就落回整行。往下走按 <code>J</code> 或 <code>S</code>，下一个落点是下一整行而不是下一行的开关，行跟行贴边错开，间距比开关那点中心距离小。</p><p>一排卡片每张带左右两颗按钮时，从卡片按 <code>L</code> 进的是这张卡片靠右的按钮；想走到下一张卡片，<code>J</code> 一下就行，不用先把按钮走完。</p><p>这些都不需要预先知道谁是容器：光标只问一句，这个方向上离我最近的是什么。</p><h2 id="什么时候消失" tabindex="-1">什么时候消失 <a class="header-anchor" href="#什么时候消失" aria-label="Permalink to &quot;什么时候消失&quot;">​</a></h2><p>光标有 4 秒不活动超时。最后一次移动之后 4 秒内没有新操作，光标自动清除；这条判定在 hint 模式显示标签期间不执行，标签还挂着的时候，光标不会因为手停下来而被收走。超时检查跟着界面刷新走，约每 32 毫秒一次。这段时间里屏幕内容变了，光标会跟着重新锚定到节点当前位置；节点消失、不可见、或尺寸归零，光标立即清除。</p><p>刷新循环只在 hint 模式或光标存在时运行，退出 hint 模式时它被整个摘掉。所以在 hint 模式里走出光标、再按 <code>Esc</code> 退出，绿框会留在屏幕上：不走超时，也不跟随界面移动，直到你再按一次方向键把它接回去。</p><p>再按 <code>F</code> 进 hint 模式时，光标先被清掉。</p><h2 id="关掉一组方向键" tabindex="-1">关掉一组方向键 <a class="header-anchor" href="#关掉一组方向键" aria-label="Permalink to &quot;关掉一组方向键&quot;">​</a></h2><p>WASD 和 HJKL 各自可以独立关闭，见<a href="/vimact-site/guide/settings.html">应用设置</a>。关掉的那组，四个字母就还给标签字符集，屏幕上的标签会更短。</p><p>保留跟着开关走：WASD 开着，<code>w</code> <code>a</code> <code>s</code> <code>d</code> 就当方向键，标签里不会出现这四个字母；把 WASD 关掉，它们立刻还给标签，哪怕 HJKL 还开着。HJKL 同理。</p>',24)])])}const _=o(t,[["render",r]]);export{u as __pageData,_ as default};
